<?php use App\Core\Csrf; ?>
<header class="page-header"><div><div class="eyebrow">Communications</div><h1>Email Centre</h1><p>Manage templates, test SMTP and inspect delivery history.</p></div><a class="secondary-button" href="/mail-setup.php">SMTP settings</a></header><?php if($flash): ?><div class="alert <?= htmlspecialchars($flash['type']) ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?>
<div class="email-grid"><section class="detail-card"><div class="panel-heading"><div><span class="eyebrow">Templates</span><h2>Transactional emails</h2></div></div><div class="template-list"><?php foreach($templates as $template): ?><a href="/emails/templates/<?= (int)$template['id'] ?>/edit"><span class="mail-icon">✉</span><span><strong><?= htmlspecialchars((string)$template['name']) ?></strong><small><?= htmlspecialchars((string)$template['subject']) ?></small></span><span class="status <?= $template['enabled']?'active':'inactive' ?>"><?= $template['enabled']?'Enabled':'Disabled' ?></span><b>›</b></a><?php endforeach; ?></div></section><aside><section class="detail-card"><div class="panel-heading"><div><span class="eyebrow">Connection</span><h2>Send test email</h2></div></div><form class="test-mail" method="post" action="/emails/test"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><label>Email address<input type="email" name="email" placeholder="you@example.com" required></label><button class="primary-button full" type="submit">Send test</button></form></section></aside></div>
<section class="list-panel email-logs"><div class="panel-heading"><div><span class="eyebrow">Delivery</span><h2>Recent email log</h2></div></div><?php if(!$logs): ?><div class="empty-state"><span>✉</span><h3>No emails sent yet</h3></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Recipient</th><th>Subject</th><th>Template</th><th>Created</th><th>Status</th><th>Error</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><strong><?= htmlspecialchars((string)($log['company_name']?:$log['contact_name']?:$log['recipient_email'])) ?></strong><small class="table-subline"><?= htmlspecialchars((string)$log['recipient_email']) ?></small></td><td><?= htmlspecialchars((string)$log['subject']) ?></td><td><?= htmlspecialchars((string)($log['template_key']?:'Test')) ?></td><td><?= date('j M Y, H:i',strtotime((string)$log['created_at'])) ?></td><td><span class="status <?= htmlspecialchars((string)$log['status']) ?>"><?= htmlspecialchars(ucfirst((string)$log['status'])) ?></span></td><td class="log-error"><?= htmlspecialchars((string)($log['error_message']?:'—')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
